class Solution {
public:
    vector<int> maxScoreIndices(vector<int>& nums) {
        int curr = 0;
        for (int x : nums) curr += x;
        int maxScore = curr;
        vector<int> best = {0};
        for (int i = 0; i < (int)nums.size(); i++) {
            if (nums[i] == 0) curr++;
            else curr--;
            if (curr > maxScore) {
                maxScore = curr;
                best = {i + 1};
            } else if (curr == maxScore) {
                best.push_back(i + 1);
            }
        }
        return best;
    }
};

class Solution {
    public List<Integer> maxScoreIndices(int[] nums) {
        int curr = 0;
        for (int x : nums) curr += x;
        int maxScore = curr;
        List<Integer> best = new ArrayList<>();
        best.add(0);
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] == 0) curr++;
            else curr--;
            if (curr > maxScore) {
                maxScore = curr;
                best.clear();
                best.add(i + 1);
            } else if (curr == maxScore) {
                best.add(i + 1);
            }
        }
        return best;
    }
}

var maxScoreIndices = function(nums) {
    let curr = nums.reduce((a, b) => a + b, 0);
    let maxScore = curr;
    let best = [0];
    for (let i = 0; i < nums.length; i++) {
        if (nums[i] === 0) curr++;
        else curr--;
        if (curr > maxScore) {
            maxScore = curr;
            best = [i + 1];
        } else if (curr === maxScore) {
            best.push(i + 1);
        }
    }
    return best;
};
